var n=`0646-mafe`;var i=`world-0646`;var a=`SN`;var s=`western-africa`;var o=4;var r=91;var g={en:`Mafé`,ua:`Мафе`};var l={en:`Mafé is a Senegal classic prepared with beef chuck, yellow onion, tomato, tomato paste. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мафе, страва кухні країни Сенегал зі складниками: яловича лопатка, жовта цибуля, помідор, томатна паста. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,610,`g`],[`sunflower-oil`,45,`ml`],[`yellow-onion`,180,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`tomato`,240,`g`],[`tomato-paste`,50,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`peanut-butter`,180,`g`],[`water`,780,`ml`],[`carrot`,250,`g`],[`sweet-potato`,320,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,22,`g`],[`table-salt`,null,`to_taste`]]}];var d={slug:n,id:i,country:`SN`,region:s,servings:4,minutes:91,title:g,text:l,steps:u};export{a as country,d as default,i as id,r as minutes,s as region,o as servings,n as slug,u as steps,l as text,g as title};